insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('356c42a2-90e5-4f83-95da-705b7f7371fb', 'N2', 'Aくて／Aなで／Vて ＋ ならない', 'Rất...đến không kìm nén được (cảm xúc/trạng thái mạnh mẽ tự nhiên, khó kiềm chế)', NULL, 'Aくて／Aなで／Vて ＋ ならない', 'Diễn tả 1 cảm xúc/trạng thái mạnh mẽ mà bản thân không thể kiềm chế được', NULL, NULL, NULL, '{}', NULL, 71, 'Aくて／Aなで／Vて ＋ ならない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('68e83800-7dac-4b19-b51f-0a2060c90348', 'N2', 'Aくて／Aなで／Vたくて／Vて ＋ たまらない', 'Rất...đến chịu không được (cảm xúc/ham muốn ở mức tối đa)', NULL, 'Aくて／Aなで／Vたくて／Vて ＋ たまらない', 'Diễn tả cảm xúc/ham muốn ở mức độ tối đa, không thể chịu đựng thêm được nữa', NULL, NULL, NULL, '{}', NULL, 71, 'Aくて／Aなで／Vたくて／Vて ＋ たまらない', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('ff0508e7-2c18-4394-88f4-45d993829c97', 'N2', 'Vます ＋ 得る', 'Có khả năng.../Có thể... (khả năng lý thuyết có thể xảy ra)', NULL, 'Vます(bỏ ます) ＋ 得る', 'Diễn tả 1 việc gì đó có khả năng/có thể xảy ra về mặt lý thuyết', NULL, NULL, NULL, '{}', NULL, 71, 'Vます ＋ 得る', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cf5dc141-0643-43e4-bcef-50c7690d29ab', 'N2', 'Vる／Aい(A1) ＋ やら Vる／Aい(A2) ＋ やら', 'Vừa...vừa.../Nào là...nào là... (liệt kê nhiều việc lộn xộn, mang sắc thái bận rộn/hỗn loạn)', NULL, 'Vる／Aい(A1) ＋ やら Vる／Aい(A2) ＋ やら', 'Liệt kê nhiều hành động/trạng thái xảy ra lộn xộn cùng lúc, mang sắc thái bận rộn/vất vả', NULL, NULL, NULL, '{}', NULL, 71, 'Vる／Aい(A1) ＋ やら Vる／Aい(A2) ＋ やら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('de85aab8-f1bf-4dd7-9dce-d9b0b62ee120', 'N2', 'N1もVれば N2も／N1もAいければ N2も／N1もAな・Nなら N2も', 'Cả N1, N2 đều... (liệt kê 2 mặt/2 đối tượng cùng có chung tính chất, thường mang sắc thái tiêu cực)', NULL, 'N1もVれば N2も／N1もAいければ N2も／N1もAな・Nなら N2も', 'Liệt kê 2 mặt/khía cạnh cùng có chung 1 tính chất (thường là tiêu cực)', NULL, NULL, NULL, '{}', NULL, 71, 'N1もVれば N2も／N1もAいければ N2も／N1もAな・Nなら N2も', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('9321a9cc-0935-4699-b945-9f3e67282509', 'N2', 'Vる／Nの ＋ 上で', '① Khi, trong trường hợp (đang làm 1 việc)　② Sau khi... (đã hoàn tất 1 việc)', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 71, 'Vる／Nの ＋ 上で', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('2be3c887-cae9-4d91-bc51-a88bd0c78330', 'N2', 'V(ます) ＋ 次第', 'Ngay sau khi... (thực hiện ngay việc tiếp theo ngay khi việc trước vừa hoàn thành)', NULL, 'Vます(bỏ ます) ＋ 次第', 'Diễn tả hành động được thực hiện ngay lập tức khi 1 điều kiện/việc trước đó vừa hoàn thành', NULL, NULL, NULL, '{}', NULL, 71, 'V(ます) ＋ 次第', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', 'N2', 'N ＋ 次第だ／で／では', '① Tùy vào (kết quả quyết định bởi yếu tố đã nêu)　② Thế nên là... (giải thích lý do/sự tình dẫn đến kết quả hiện tại)', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 71, 'N ＋ 次第だ／で／では', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('014a4da3-745a-4629-ba56-4f3481b3dba7', 'N2', 'Vた／Nの ＋ あげく', 'Kết cục thì.../Cuối cùng thì... (sau 1 quá trình dài, thường dẫn đến kết quả không mấy tốt đẹp)', NULL, 'Vた／Nの ＋ あげく', 'Diễn tả kết quả cuối cùng (thường tiêu cực) sau 1 quá trình dài đã trải qua', NULL, NULL, NULL, '{}', NULL, 71, 'Vた／Nの ＋ あげく', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('5aec666c-2ea2-4c38-a2ab-74afa489ef86', '9321a9cc-0935-4699-b945-9f3e67282509', 1, 'Khi, trong trường hợp (đang trong quá trình thực hiện 1 việc)', 'Vる／Nの ＋ 上で', 'Nêu bối cảnh/điều kiện quan trọng cần lưu ý khi đang thực hiện 1 việc', NULL, 71, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('4f3476c7-dd2e-4039-bd62-fad21ce38b51', '9321a9cc-0935-4699-b945-9f3e67282509', 2, 'Sau khi... (đã hoàn tất 1 việc rồi mới làm việc tiếp theo)', 'Vた／Nの ＋ 上で', 'Diễn tả 1 hành động được thực hiện sau khi đã hoàn tất 1 việc trước đó', NULL, 71, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('09e3dcf5-6b2b-4eb2-90d2-6e0e47d0deb0', 'bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', 1, 'Tùy vào (kết quả được quyết định hoàn toàn bởi yếu tố đã nêu)', 'N ＋ 次第だ／で／では', 'Diễn tả kết quả/quyết định hoàn toàn phụ thuộc vào yếu tố đã nêu', NULL, 71, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('849d274f-8bca-441f-b7da-978aa07db1c2', 'bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', 2, 'Thế nên là... (giải thích lý do/quá trình sự việc dẫn đến kết quả/tình huống hiện tại)', '普通形(Aな／Nである) ＋ 次第だ', 'Giải thích lý do/quá trình dẫn đến 1 kết quả/tình huống hiện tại, mang tính trang trọng', NULL, 71, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('356c42a2-90e5-4f83-95da-705b7f7371fb', NULL, 1, 'standard', 'この道は街灯がなく、辺りが見えにくいので危なくてならない。', 'Con đường này vì không có đèn đường và không nhìn được xung quanh nên rất nguy hiểm.', 'この道は街灯がなく、辺りが見えにくいので危なく＿＿＿。', 'てならない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('356c42a2-90e5-4f83-95da-705b7f7371fb', NULL, 2, 'daily', '彼のことが心配でならない。', 'Tôi lo lắng cho anh ấy đến mức không kìm được.', '彼のことが心配＿＿＿。', 'でならない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('356c42a2-90e5-4f83-95da-705b7f7371fb', NULL, 3, 'daily', '久しぶりに故郷に帰れることが嬉しくてならない。', 'Tôi vui mừng đến không kìm được vì lâu lắm mới được về quê.', '久しぶりに故郷に帰れることが嬉しく＿＿＿。', 'てならない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('68e83800-7dac-4b19-b51f-0a2060c90348', NULL, 1, 'standard', 'ホラー映画を観てから、トイレが怖くてたまらない。', 'Sau khi xem phim kinh dị tôi vô cùng sợ đi toilet.', 'ホラー映画を観てから、トイレが怖くて＿＿＿。', 'たまらない', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('68e83800-7dac-4b19-b51f-0a2060c90348', NULL, 2, 'daily', 'お腹が空いてたまらない。', 'Tôi đói đến mức chịu không nổi.', 'お腹が空いて＿＿＿。', 'たまらない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('68e83800-7dac-4b19-b51f-0a2060c90348', NULL, 3, 'daily', '彼女に会いたくてたまらない。', 'Tôi nhớ cô ấy đến mức không chịu được.', '彼女に会いたくて＿＿＿。', 'たまらない', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ff0508e7-2c18-4394-88f4-45d993829c97', NULL, 1, 'standard', 'どんなに優秀な人でも、間違いを起こすことはあり得る。', 'Dù là người ưu tú như thế nào thì những sai sót cũng có thể xảy ra.', 'どんなに優秀な人でも、間違いを起こすことはあり＿＿＿。', '得る', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ff0508e7-2c18-4394-88f4-45d993829c97', NULL, 2, 'daily', 'その事故は誰にでも起こり得る。', 'Tai nạn đó có thể xảy ra với bất kỳ ai.', 'その事故は誰にでも起こり＿＿＿。', '得る', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('ff0508e7-2c18-4394-88f4-45d993829c97', NULL, 3, 'daily', 'この計画は実現し得ると思う。', 'Tôi nghĩ kế hoạch này có thể thực hiện được.', 'この計画は実現し＿＿＿と思う。', '得る', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cf5dc141-0643-43e4-bcef-50c7690d29ab', NULL, 1, 'standard', '母はいつも、掃除をするやら買い物に行くやら忙しい。', 'Mẹ tôi lúc nào cũng bận nào là dọn dẹp nào là đi mua đồ.', '母はいつも、掃除をする＿＿＿買い物に行く＿＿＿忙しい。', 'やら／やら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cf5dc141-0643-43e4-bcef-50c7690d29ab', NULL, 2, 'daily', '引っ越しの日は荷造りをするやら掃除をするやらで大変だった。', 'Ngày chuyển nhà thật vất vả, nào là đóng gói đồ nào là dọn dẹp.', '引っ越しの日は荷造りをする＿＿＿掃除をする＿＿＿で大変だった。', 'やら／やら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cf5dc141-0643-43e4-bcef-50c7690d29ab', NULL, 3, 'daily', '彼は嬉しいやら恥ずかしいやらで、顔を赤くした。', 'Anh ấy vừa vui vừa xấu hổ nên đỏ cả mặt.', '彼は嬉しい＿＿＿恥ずかしい＿＿＿で、顔を赤くした。', 'やら／やら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('de85aab8-f1bf-4dd7-9dce-d9b0b62ee120', NULL, 1, 'standard', '私は勉強も苦手なら、運動も苦手で自分のことが嫌になる。', 'Tôi không giỏi về học tập cũng như vận động nên cảm thấy chán ghét chính bản thân mình.', '私は勉強も苦手＿＿＿、運動も苦手で自分のことが嫌になる。', 'なら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('de85aab8-f1bf-4dd7-9dce-d9b0b62ee120', NULL, 2, 'daily', '彼は歌も歌えれば、ダンスも踊れる。', 'Anh ấy vừa có thể hát vừa có thể nhảy múa.', '彼は歌も歌え＿＿＿、ダンスも踊れる。', 'れば', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('de85aab8-f1bf-4dd7-9dce-d9b0b62ee120', NULL, 3, 'daily', 'このアパートは家賃も安ければ、駅からも近い。', 'Căn hộ này vừa giá thuê rẻ vừa gần ga.', 'このアパートは家賃も安＿＿＿、駅からも近い。', 'ければ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '5aec666c-2ea2-4c38-a2ab-74afa489ef86', 1, 'standard', '外国人との交流の上で重要なのは、相手の文化を知ろうとすることだ。', 'Khi giao lưu với người nước ngoài, điều quan trọng là cố gắng tìm hiểu về văn hóa của đối phương.', '外国人との交流の＿＿＿重要なのは、相手の文化を知ろうとすることだ。', '上で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '5aec666c-2ea2-4c38-a2ab-74afa489ef86', 2, 'daily', 'この仕事を進める上で、チームワークが欠かせない。', 'Khi tiến hành công việc này, tinh thần đồng đội là không thể thiếu.', 'この仕事を進める＿＿＿、チームワークが欠かせない。', '上で', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '5aec666c-2ea2-4c38-a2ab-74afa489ef86', 3, 'daily', '契約の上で、いくつか確認すべき点がある。', 'Trong quá trình ký hợp đồng, có vài điểm cần xác nhận.', '契約の＿＿＿、いくつか確認すべき点がある。', '上で', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '4f3476c7-dd2e-4039-bd62-fad21ce38b51', 1, 'standard', 'SNSで何度もやり取りをした上で、彼と実際に会うことに決めた。', 'Sau khi liên lạc nhiều lần qua mạng xã hội, tôi đã quyết định gặp anh ấy ngoài đời.', 'SNSで何度もやり取りをした＿＿＿、彼と実際に会うことに決めた。', '上で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '4f3476c7-dd2e-4039-bd62-fad21ce38b51', 2, 'daily', 'よく考えた上で、返事をします。', 'Sau khi suy nghĩ kỹ, tôi sẽ trả lời.', 'よく考えた＿＿＿、返事をします。', '上で', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9321a9cc-0935-4699-b945-9f3e67282509', '4f3476c7-dd2e-4039-bd62-fad21ce38b51', 3, 'daily', '資料を確認した上で、決定します。', 'Sau khi xác nhận tài liệu, tôi sẽ quyết định.', '資料を確認した＿＿＿、決定します。', '上で', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2be3c887-cae9-4d91-bc51-a88bd0c78330', NULL, 1, 'standard', '準備が整い次第、すぐに作業に移る。', 'Khi mọi chuyện được chuẩn bị sẵn sàng thì lập tức bắt tay vào làm.', '準備が整い＿＿＿、すぐに作業に移る。', '次第', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2be3c887-cae9-4d91-bc51-a88bd0c78330', NULL, 2, 'daily', '到着次第、ご連絡いたします。', 'Ngay khi đến nơi, tôi sẽ liên lạc ngay.', '到着＿＿＿、ご連絡いたします。', '次第', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('2be3c887-cae9-4d91-bc51-a88bd0c78330', NULL, 3, 'daily', '結果が分かり次第、お知らせします。', 'Ngay khi biết kết quả, tôi sẽ thông báo.', '結果が分かり＿＿＿、お知らせします。', '次第', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '09e3dcf5-6b2b-4eb2-90d2-6e0e47d0deb0', 1, 'standard', '明日の天気次第でどこにデートで行くかが決まる。', 'Tùy vào thời tiết ngày mai mà sẽ đi hẹn hò ở đâu.', '明日の天気＿＿＿どこにデートで行くかが決まる。', '次第で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '09e3dcf5-6b2b-4eb2-90d2-6e0e47d0deb0', 2, 'daily', '成功するかどうかは君の努力次第だ。', 'Có thành công hay không là tùy vào sự nỗ lực của cậu.', '成功するかどうかは君の努力＿＿＿。', '次第だ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '09e3dcf5-6b2b-4eb2-90d2-6e0e47d0deb0', 3, 'daily', '参加できるかは仕事の都合次第では変わる。', 'Có tham gia được hay không sẽ thay đổi tùy vào lịch công việc.', '参加できるかは仕事の都合＿＿＿変わる。', '次第では', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '849d274f-8bca-441f-b7da-978aa07db1c2', 1, 'standard', '彼とは大学で知り合い、卒業後にプロポーズされて結婚した次第だ。', 'Tôi quen anh ở Đại học, sau khi tốt nghiệp được anh ấy cầu hôn nên chúng tôi đã kết hôn.', '彼とは大学で知り合い、卒業後にプロポーズされて結婚した＿＿＿。', '次第だ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '849d274f-8bca-441f-b7da-978aa07db1c2', 2, 'daily', '急用ができたので、欠席させていただく次第です。', 'Vì có việc gấp nên tôi xin phép vắng mặt.', '急用ができたので、欠席させていただく＿＿＿。', '次第です', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bf4c28f3-bba2-4b3d-b9f8-fc50731ef395', '849d274f-8bca-441f-b7da-978aa07db1c2', 3, 'daily', '色々調べた結果、この結論に至った次第だ。', 'Sau khi tìm hiểu nhiều thứ, tôi đã đi đến kết luận này.', '色々調べた結果、この結論に至った＿＿＿。', '次第だ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('014a4da3-745a-4629-ba56-4f3481b3dba7', NULL, 1, 'standard', '日々の重労働のあげく、上司は病気にかかり入院することとなった。', 'Sau những ngày lao động nặng nhọc, sếp của tôi bị bệnh và nhập viện.', '日々の重労働＿＿＿、上司は病気にかかり入院することとなった。', 'のあげく', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('014a4da3-745a-4629-ba56-4f3481b3dba7', NULL, 2, 'daily', '長時間悩んだあげく、彼は会社を辞めることにした。', 'Sau khi trăn trở suy nghĩ rất lâu, cuối cùng anh ấy quyết định nghỉ việc.', '長時間悩んだ＿＿＿、彼は会社を辞めることにした。', 'あげく', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('014a4da3-745a-4629-ba56-4f3481b3dba7', NULL, 3, 'daily', 'さんざん迷ったあげく、結局何も買わなかった。', 'Sau khi phân vân mãi, cuối cùng tôi chẳng mua gì cả.', 'さんざん迷った＿＿＿、結局何も買わなかった。', 'あげく', 'generated');
